import{_ as o,o as n,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const N=JSON.parse('{"title":"EPSILON","description":"在 JavaScript 中，EPSILON 这个常量名通常表示一个​ ​ 极小的正数 ​ ​（如 1e 9，即 0.000000001），主要用于处理​ ​ 浮点数精度问题 ​ ​。以下是它的核心意义和常见用途： 1. ​​ 解决浮点数比较问题 ​​ JavaScript 使用。","frontmatter":{"title":"EPSILON","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","语法、变量与数据"],"description":"在 JavaScript 中，EPSILON 这个常量名通常表示一个​ ​ 极小的正数 ​ ​（如 1e 9，即 0.000000001），主要用于处理​ ​ 浮点数精度问题 ​ ​。以下是它的核心意义和常见用途： 1. ​​ 解决浮点数比较问题 ​​ JavaScript 使用。","sidebarWeight":18,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/变量和常量/常见常量/EPSILON.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/02-语法、变量与数据/常见常量/EPSILON.md","filePath":"posts/JavaScript系统教程/02-语法、变量与数据/常见常量/EPSILON.md"}'),a={name:"posts/JavaScript系统教程/02-语法、变量与数据/常见常量/EPSILON.md"};function e(g,t,i,l,p,c){return n(),r("div",null,[...t[0]||(t[0]=[s('<div><h1 id="epsilon" tabindex="-1">EPSILON <a class="header-anchor" href="#epsilon" aria-label="Permalink to &quot;EPSILON&quot;">​</a></h1><blockquote><p>本节目标：理解“EPSILON”的核心思路，并能把它用于实际开发或面试表达。 在 JavaScript 中，EPSILON 这个常量名通常表示一个​<strong>​<strong><strong>极小的正数</strong></strong>​</strong>​（如 1e-9，即 0.000000001），主要用于处理​<strong>​<strong><strong>浮点数精度问题</strong></strong>​</strong>​。以下是它的核心意义和常见用途：</p></blockquote><p><strong>1.</strong> <strong>​​<strong><strong>解决浮点数比较问题</strong></strong>​​</strong> JavaScript 使用 IEEE 754 双精度浮点数，可能导致如下经典问题： console.log(0.1 + 0.2 === 0.3); // false（实际结果为 0.30000000000000004） 通过 EPSILON 可以安全比较浮点数： function floatEqual(a, b, epsilon = EPSILON) { return Math.abs(a - b) &lt; epsilon;}console.log(floatEqual(0.1 + 0.2, 0.3)); // true</p><p><strong>2.</strong> <strong>​​<strong><strong>避免除以零的错误</strong></strong>​​</strong> 在数学计算中，用 EPSILON 防止分母为零： function safeDivide(a, b) { return a / (b + EPSILON); // 避免 b=0 时 Infinity}</p><p><strong>3.</strong> <strong>​​<strong><strong>图形计算/游戏开发</strong></strong>​​</strong> 在需要高精度计算的场景（如向量运算、碰撞检测）中，EPSILON 用于： // 判断点是否在直线上function isPointOnLine(point, line) { return Math.abs(distance(point, line)) &lt; EPSILON;}</p><p><strong>4.</strong> <strong>​​<strong><strong>与 JavaScript 原生 Number.EPSILON 的区别</strong></strong>​​</strong></p><ul><li>你定义的 EPSILON = 1e-9 是自定义的阈值，适用于大多数业务场景。</li><li>JS 原生的 Number.EPSILON（≈ 2.22e-16）表示​<strong>​<strong><strong>最小可表示差值</strong></strong>​</strong>​，通常用于更严格的数值计算。</li></ul><p><strong>5.</strong> <strong>​​<strong><strong>其他常见用途</strong></strong>​​</strong></p><ul><li>​<strong>​<strong><strong>动画/插值</strong></strong>​</strong>​：判断动画是否到达目标位置。 if (Math.abs(currentPos - targetPos) &lt; EPSILON) stopAnimation();</li><li>​<strong>​<strong><strong>机器学习</strong></strong>​</strong>​：梯度下降等算法中的收敛判断。</li></ul><p><strong>最佳实践</strong></p><ul><li>​<strong>​<strong><strong>命名建议</strong></strong>​</strong>​：如果用途明确，可命名更具体（如 POSITION_EPSILON、ANGLE_EPSILON）。</li><li>​<strong>​<strong><strong>值的选择</strong></strong>​</strong>​：1e-9 对大多数场景足够小，但物理仿真可能需要更小（如 1e-12）。</li></ul><p>总之，EPSILON 是处理浮点数精度问题的“安全阀”，平衡了计算精度与性能。 &gt; 来自 &lt;<a href="https://yuanbao.tencent.com/chat/naQivTmsDa/daff0653-38c5-4fb1-aa6d-eda6e62a38d4" target="_blank" rel="noreferrer">https://yuanbao.tencent.com/chat/naQivTmsDa/daff0653-38c5-4fb1-aa6d-eda6e62a38d4</a>&gt;</p></div>',1)])])}const P=o(a,[["render",e]]);export{N as __pageData,P as default};
